int cipso_v4_doi_add(struct genl_info *info, struct cipso_v4_doi *doi_def)
{
    struct nlattr *tb[DOI_ATTR_MAX + 1];
    struct nlattr *tag_attr;
    int rem;
    int tag_count = 0;

    if (!info || !doi_def)
        return -EINVAL;

    if (nla_parse_nested(tb, DOI_ATTR_MAX, info->attrs[DOI_ATTR_TAGS],
                         NULL)) {
        return -EINVAL;
    }

    if (!tb[DOI_ATTR_DOI])
        return -EINVAL;

    doi_def->doi = nla_get_u32(tb[DOI_ATTR_DOI]);

    doi_def->tags = 0;
    nla_for_each_nested(tag_attr, tb[DOI_ATTR_TAGS], rem) {
        if (tag_count >= CIPSO_V4_MAX_TAGS)
            return -EINVAL;

        if (nla_len(tag_attr) != sizeof(u16))
            return -EINVAL;

        doi_def->tags[tag_count++] = nla_get_u16(tag_attr);
    }

    /* Mark unused tag storage with invalid tag value */
    while (tag_count < CIPSO_V4_MAX_TAGS)
        doi_def->tags[tag_count++] = CIPSO_V4_INVALID_TAG;

    return 0;
}

